package dev.kuan.kuanperion.automation.supercraft;
import dev.kuan.kuanperion.automation.*;import java.util.*;import java.util.concurrent.atomic.*;
public final class SupercraftReceiptsTest {
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 static final class H {
  Map<Integer,ItemSnapshot> before=SupercraftPlanTest.inventory();InventoryReceipts items=new InventoryReceipts();CursorReceipts cursor=new CursorReceipts();AtomicBoolean owned=new AtomicBoolean(true);
  SupercraftReceipts proof=new SupercraftReceipts(items,cursor,owned::get);SupercraftPlan.Plan plan=SupercraftPlan.select(SupercraftPlanTest.RECIPE,2,SupercraftPlanTest.RULES,before).orElseThrow();
  MenuSnapshot menu(){var slots=new ArrayList<MenuSnapshot.Slot>();for(int i=0;i<36;i++)slots.add(new MenuSnapshot.Slot(54+i,before.get(i<27?i+9:i-27),true));return new MenuSnapshot(1,7,5,"Supercraft",54,slots);}
  void arm(){check(proof.arm(plan,menu(),before,true,1),"complete read-only pre-click baseline");}void start(){arm();check(proof.sent(GuardedMenuAction.Result.SENT,2),"record actual guarded send once");}
  Map<Integer,ItemSnapshot> result(boolean server){var after=new HashMap<>(before);for(int i=9;i<14;i++){after.put(i,SupercraftPlanTest.AIR);if(server)items.observe(1,0,i,after.get(i));}after.put(14,SupercraftPlanTest.item("ENCHANTED_WHEAT",2,false,""));if(server)items.observe(1,0,14,after.get(14));return after;}
  void cursor(){cursor.observe(1,7,SupercraftPlanTest.AIR,3);}void poll(Map<Integer,ItemSnapshot> current){proof.poll(1,current,true,4);}
 }
 public static void main(String[]args){
  var h=new H();h.start();h.cursor();h.poll(h.result(false));check(h.proof.state()==SupercraftReceipts.State.AWAITING,"predicted input/output mutations do not prove craft");h.poll(h.result(true));check(h.proof.state()==SupercraftReceipts.State.CONFIRMED&&!h.proof.sent(GuardedMenuAction.Result.SENT,5)&&!h.proof.arm(h.plan,h.menu(),h.before,true,5),"all exact server deltas + empty cursor confirms one irreversible attempt only");
  var noCursor=new H();noCursor.start();noCursor.poll(noCursor.result(true));check(noCursor.proof.state()==SupercraftReceipts.State.AWAITING,"physical empty alone not proof");noCursor.cursor();noCursor.proof.poll(1,noCursor.result(true),false,4);check(noCursor.proof.state()==SupercraftReceipts.State.AWAITING,"new held physical cursor blocks confirmation");
  var old=new H();old.result(true);old.cursor();old.start();old.poll(old.result(false));check(old.proof.state()==SupercraftReceipts.State.AWAITING,"receipts predating actual guarded send cannot prove attempt");
  var missing=new H();missing.start();missing.cursor();var result=missing.result(true);result.put(14,SupercraftPlanTest.AIR);missing.poll(result);check(missing.proof.state()==SupercraftReceipts.State.AWAITING,"consumption without actual output never success");
  var extra=new H();extra.start();extra.cursor();var tooMuch=extra.result(true);tooMuch.put(14,SupercraftPlanTest.item("ENCHANTED_WHEAT",3,false,""));extra.items.observe(1,0,14,tooMuch.get(14));extra.poll(tooMuch);check(extra.proof.state()==SupercraftReceipts.State.AWAITING,"never accept maximized/unrequested output quantity");
  var partial=new H();partial.start();partial.cursor();var shortLoss=partial.result(true);shortLoss.put(9,SupercraftPlanTest.item("WHEAT",1,false,""));partial.items.observe(1,0,9,shortLoss.get(9));partial.poll(shortLoss);check(partial.proof.state()==SupercraftReceipts.State.AWAITING,"every ingredient loss must exactly match configured batch");
  for(int slot:List.of(0,36,40,41,42)){var p=new H();p.start();p.cursor();var changed=p.result(true);changed.put(slot,SupercraftPlanTest.item("STONE",1,false,""));p.poll(changed);check(p.proof.state()==SupercraftReceipts.State.AWAITING,"protected hotbar/equipment must stay unchanged: "+slot);}
  var unrelated=new H();unrelated.start();unrelated.cursor();var changed=unrelated.result(true);changed.put(20,SupercraftPlanTest.item("STONE",1,false,""));unrelated.items.observe(1,0,20,changed.get(20));unrelated.poll(changed);check(unrelated.proof.state()==SupercraftReceipts.State.AWAITING,"unrelated server mutation is not an authorized craft result");
  var oneMissing=new H();oneMissing.start();oneMissing.cursor();var predicted=oneMissing.result(true);predicted.put(15,predicted.get(14));predicted.put(14,SupercraftPlanTest.AIR);oneMissing.items.observe(1,0,14,SupercraftPlanTest.AIR);oneMissing.poll(predicted);check(oneMissing.proof.state()==SupercraftReceipts.State.AWAITING,"all affected final slots require matching post-stamp server evidence");
  var window=new H();window.start();window.cursor();var inMenu=window.result(false);for(int i=9;i<=14;i++)window.items.observe(1,7,54+i-9,inMenu.get(i));window.poll(inMenu);check(window.proof.state()==SupercraftReceipts.State.CONFIRMED,"exact active container player-slot receipts also accepted");
  var reject=new H();reject.arm();check(!reject.proof.sent(GuardedMenuAction.Result.REJECTED,2)&&reject.proof.state()==SupercraftReceipts.State.REJECTED,"definite native guard refusal terminal");
  var uncertain=new H();uncertain.arm();check(!uncertain.proof.sent(GuardedMenuAction.Result.UNCERTAIN,2)&&uncertain.proof.state()==SupercraftReceipts.State.UNCERTAIN,"ambiguous native send is not safe to retry");
  var revoked=new H();revoked.start();revoked.owned.set(false);revoked.cursor();revoked.poll(revoked.result(true));check(revoked.proof.state()==SupercraftReceipts.State.UNCERTAIN,"manual revoked root cannot confirm later receipts");
  var world=new H();world.start();world.proof.poll(2,world.result(true),true,4);check(world.proof.state()==SupercraftReceipts.State.UNCERTAIN,"world change stops proof");
  var timeout=new H();timeout.start();timeout.proof.poll(1,timeout.before,true,15_000_000_002L);check(timeout.proof.state()==SupercraftReceipts.State.UNCERTAIN,"bounded no-retry deadline");
  var late=new H();late.arm();check(!late.proof.sent(GuardedMenuAction.Result.SENT,1_000_000_001L)&&late.proof.state()==SupercraftReceipts.State.UNCERTAIN,"pre-click stamp must be close to actual send, not a stale prepared GUI");
  var clock=new H();clock.start();clock.proof.poll(1,clock.before,true,1);check(clock.proof.state()==SupercraftReceipts.State.UNCERTAIN,"clock reversal after sent is terminal, even within the armed window");
  var changedGear=new H();changedGear.before.put(42,SupercraftPlanTest.item("WHEAT",1,false,""));check(!changedGear.proof.arm(changedGear.plan,changedGear.menu(),changedGear.before,true,1),"complete43 baseline including hidden equipment is revalidated before arming");
  var between=new H();between.arm();between.result(true);between.cursor.observe(1,7,SupercraftPlanTest.AIR,1);between.proof.sent(GuardedMenuAction.Result.SENT,2);between.poll(between.result(false));check(between.proof.state()==SupercraftReceipts.State.AWAITING,"receipts between prepare and actual send cannot be borrowed");between.cursor();between.poll(between.result(true));check(between.proof.state()==SupercraftReceipts.State.CONFIRMED,"new post-send evidence is required");
  System.out.println("SupercraftReceiptsTest: PASS (pre-send immutable baseline, exact input/output/all-slot applied receipts + cursor, one attempt, protected/unrelated/replay/prediction/world/manual/timeout denial; no GUI authority)");
 }
}
